class Solution {
  public int dietPlanPerformance(int[] calories, int k, int lower, int upper) {
    int points = 0;
    long window = 0;
    for (int i = 0; i < calories.length; i++) {
      window += calories[i];
      if (i >= k) window -= calories[i - k];
      if (i >= k - 1) {
        if (window < lower) points--;
        else if (window > upper) points++;
      }
    }
    return points;
  }
}
